        while (true) {
            try {
                Timber.i("SignalRDataService: attempting reconnect")
                hubConnection.start().blockingAwait()
                Timber.i("SignalRDataService: reconnected successfully")
                break
            } catch (ex: Exception) {
                Timber.e(ex, "SignalRDataService: reconnect failed, retrying in 5s")
                delay(5000)
            }
        }
