import android.annotation.SuppressLint
import android.content.Context
import android.location.Location
import com.google.android.gms.location.*
import dagger.hilt.android.qualifiers.ApplicationContext
import javax.inject.Inject
import javax.inject.Singleton
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import timber.log.Timber
import kdi.logistixs.domain.interfaces.backgroundservices.ISignalRTrackingService
import kdi.logistixs.domain.models.objects.LocationModel
import com.kdi.infrastructure.backgroundservices.signalr.GenericSignalRClient

@Singleton
class SignalRTrackingService @Inject constructor(
    @ApplicationContext private val context: Context,
    private val signalRClient: GenericSignalRClient
) : ISignalRTrackingService {

    companion object {
        private const val LOCATION_INTERVAL_MS = 10_000L
        private const val FASTEST_INTERVAL_MS = 5_000L
        private const val HUB_METHOD = "SendLocation"
    }

    private val fusedClient = LocationServices.getFusedLocationProviderClient(context)
    private lateinit var locationCallback: LocationCallback

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)

    override fun startService() {
        signalRClient.startService()
        startLocationUpdates()
    }

    override fun stopService() {
        scope.launch {
            fusedClient.removeLocationUpdates(locationCallback)
            signalRClient.stopService()
            scope.cancel()
        }
    }

    @SuppressLint("MissingPermission")
    private fun startLocationUpdates() {
        val request = LocationRequest.create().apply {
            interval = LOCATION_INTERVAL_MS
            fastestInterval = FASTEST_INTERVAL_MS
            priority = Priority.PRIORITY_HIGH_ACCURACY
        }

        locationCallback = object : LocationCallback() {
            override fun onLocationResult(result: LocationResult) {
                result.lastLocation?.let { sendLocation(it) }
            }
        }

        fusedClient.requestLocationUpdates(request, locationCallback, null)
        Timber.i("SignalRTrackingService: requested location updates")
    }

    private fun sendLocation(location: Location) {
        val model = LocationModel(
            latitude = location.latitude,
            longitude = location.longitude,
            accuracy = location.accuracy.toDouble(),
            timestamp = location.time,
            speed = location.speed.toDouble(),
            bearing = location.bearing.toDouble()
        )
        signalRClient.send(HUB_METHOD, model)
    }
}"}]}

